#include <bits/stdc++.h>
using namespace std;

long long powMod(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, l, r;
    cin >> n >> m;
    long long k = n * m;
    cin >> l >> r;
    long long length = r - l + 1;
    const long long MOD = 998244353;

    if (k % 2 != 0) {
        cout << powMod(length, n * m, MOD) << "\n";
    } else {
        long long val1 = powMod(length, k, MOD);
        long long val2 = powMod(length % 2, k, MOD);
        long long inv2 = powMod(2, MOD - 2, MOD);
        long long answer = ((val1 + val2) % MOD) * inv2 % MOD;
        cout << answer << "\n";
    }
    return 0;
}

